    {
      "dependency_id": "R3K06-C1-D1",
      "subject": "Neither option has conclusive diagnostic evidence.",
      "dependency_classification": {
        "content_origin": "TARGET_SUPPLIED",
        "epistemic_function": "FACT",
        "assertion_mode": "REFERENCED_PREMISE",
        "origin_refs": [
          {
            "source_id": "R3K06-T",
            "source_type": "TARGET"
          }
        ],
        "rationale": "The target explicitly supplies diagnostic inconclusiveness for both options. This describes the case's evidential state and is invoked as the deployment rule's trigger."
      },
      "resolution": "GROUNDING_REF",
      "claim_ref": null,
      "provenance_refs": [
        {
          "source_id": "R3K06-T",
          "role": "SUPPORT"
        }
      ],
      "materiality_rationale": "This premise establishes that the rule's triggering condition holds in the frozen case.",
      "resolution_rationale": "The claim invokes the supplied diagnostic state at the same scope and certainty, without extending it."
    },
    {
      "dependency_id": "R3K06-C1-D2",
      "subject": "B is an authorized deployment choice.",
      "dependency_classification": {
        "content_origin": "TARGET_SUPPLIED",
        "epistemic_function": "FACT",
        "assertion_mode": "REFERENCED_PREMISE",
        "origin_refs": [
          {
            "source_id": "R3K06-T",
            "source_type": "TARGET"
          }
        ],
        "rationale": "The target explicitly includes B among the authorized deployment choices. This is a supplied authorization state invoked by the prospective deployment rule."
      },
      "resolution": "GROUNDING_REF",
      "claim_ref": null,
      "provenance_refs": [
        {
          "source_id": "R3K06-T",
          "role": "SUPPORT"
        }
      ],
      "materiality_rationale": "Removing B's authorization would materially change the basis for prescribing its deployment under the frozen conditions.",
      "resolution_rationale": "The dependency merely invokes B's supplied authorization, without creating or expanding permission."
    },
    {
      "dependency_id": "R3K06-C1-D3",
      "subject": "B's reversible configuration-switch procedure satisfies the supplied applicability and safety requirements.",
      "dependency_classification": {
        "content_origin": "TARGET_SUPPLIED",
        "epistemic_function": "FACT",
        "assertion_mode": "REFERENCED_PREMISE",
        "origin_refs": [
          {
            "source_id": "R3K06-T",
            "source_type": "TARGET"
          }
        ],
        "rationale": "The target explicitly supplies this procedural status for B. It is a descriptive prerequisite invoked by deployment, without asserting comparative reversal safety."
      },
      "resolution": "GROUNDING_REF",
      "claim_ref": null,
      "provenance_refs": [
        {
          "source_id": "R3K06-T",
          "role": "SUPPORT"
        },
        {
          "source_id": "R3K06-S",
          "role": "CONTEXT"
        }
      ],
      "materiality_rationale": "The prescription depends on the deployment procedure being applicable and satisfying the supplied safety requirements.",
      "resolution_rationale": "The dependency preserves the target's supplied requirements and scope. It adds no claim that B is comparatively safer."
    },
    {
      "dependency_id": "R3K06-C1-D4",
      "subject": "Perform the documented configuration switch to deploy B.",
      "dependency_classification": {
        "content_origin": "SOURCE_SUPPLIED",
        "epistemic_function": "OPERATION",
        "assertion_mode": "ASSERTED_COMPONENT",
        "origin_refs": [
          {
            "source_id": "R3K06-S",
            "source_type": "SOURCE_INSTRUMENT"
          }
        ],
        "rationale": "The source supplies the documented configuration-switch operation and explicitly makes it applicable to B. This is a substantive intervention. The mapping clarifies that the claim prescribes performing it; the B-first selection rule remains the frozen generated primary assertion."
      },
      "resolution": "INLINE_OBLIGATION",
      "claim_ref": null,
      "provenance_refs": [
        {
          "source_id": "R3K06-S",
          "role": "SUPPORT"
        },
        {
          "source_id": "R3K06-T",
          "role": "CONTEXT"
        },
        {
          "source_id": "R3K06-M",
          "role": "CONTEXT"
        }
      ],
      "materiality_rationale": "Replacing actual configuration switching with merely recording a decision would change the prescribed action materially.",
      "resolution_rationale": "The claim asserts performance of a substantive supplied operation. It is not merely referencing the procedure or prescribing an ordinary stop or rollback, and no separate frozen claim evaluates it."
    },
    {
      "dependency_id": "R3K06-C1-D5",
      "subject": "B is safer to reverse.",
      "dependency_classification": {
        "content_origin": "MAPPING_GENERATED",
        "epistemic_function": "FACT",
        "assertion_mode": "ASSERTED_COMPONENT",
        "origin_refs": [],
        "rationale": "Neither input supplies B's comparative reversal-safety advantage. The mapping introduces that descriptive comparison as the asserted reason for choosing B, without framing it as a derivation from observations."
      },
      "resolution": "INLINE_OBLIGATION",
      "claim_ref": null,
      "provenance_refs": [
        {
          "source_id": "R3K06-T",
          "role": "CONTEXT"
        },
        {
          "source_id": "R3K06-S",
          "role": "CONTEXT"
        },
        {
          "source_id": "R3K06-M",
          "role": "CONTEXT"
        }
      ],
      "materiality_rationale": "The claim expressly bases its B-first prescription on this comparison. Removing it would replace the stated rationale with an unsupported policy preference and change the claim's meaning.",
      "resolution_rationale": "This generated substantive assertion requires separate treatment. It cannot use grounding, and the inventory contains no other frozen evaluated claim to reference. Its evidential validity is not evaluated here."
    }
  ],
